func TestIamPolicyReadWithRetry_concurrentReadsOfOnePolicy(t *testing.T) {
	t.Parallel()

	const readers = 5
	updater := &blockingIamUpdater{resourceId: "concurrent-reads", release: make(chan struct{})}

	errCh := make(chan error, readers)
	for i := 0; i < readers; i++ {
		go func() {
			_, err := iamPolicyReadWithRetry(updater)
			errCh <- err
		}()
	}

	// Every read blocks inside getIamPolicy, so all of them only get there if
	// they hold the per-resource lock at the same time.
	deadline := time.Now().Add(time.Second)
	for atomic.LoadInt32(&updater.reads) < readers && time.Now().Before(deadline) {
		time.Sleep(10 * time.Millisecond)
	}
	got := atomic.LoadInt32(&updater.reads)
	close(updater.release)
	if got != readers {
		t.Fatalf("expected %d concurrent getIamPolicy calls on one policy, got %d: reads are serialized", readers, got)
	}
	for i := 0; i < readers; i++ {
		if err := <-errCh; err != nil {
			t.Fatalf("iamPolicyReadWithRetry: %v", err)
		}
	}
}

func TestIamPolicyReadWithRetry_waitsForInFlightWrite(t *testing.T) {
	t.Parallel()

	updater := &blockingIamUpdater{resourceId: "read-waits-for-write", release: make(chan struct{})}
	close(updater.release)

	// Hold the lock the way iamPolicyReadModifyWrite does for its whole
	// read-modify-write and propagation check.
	transport_tpg.MutexStore.Lock(updater.GetMutexKey())
	errCh := make(chan error, 1)
	go func() {
		_, err := iamPolicyReadWithRetry(updater)
		errCh <- err
	}()

	select {
	case err := <-errCh:
		transport_tpg.MutexStore.Unlock(updater.GetMutexKey())
		t.Fatalf("read completed while a write held the lock (err: %v)", err)
	case <-time.After(100 * time.Millisecond):
	}
	if got := atomic.LoadInt32(&updater.reads); got != 0 {
		transport_tpg.MutexStore.Unlock(updater.GetMutexKey())
		t.Fatalf("expected no getIamPolicy call while a write held the lock, got %d", got)
	}
	transport_tpg.MutexStore.Unlock(updater.GetMutexKey())

	select {
	case err := <-errCh:
		if err != nil {
			t.Fatalf("iamPolicyReadWithRetry: %v", err)
		}
	case <-time.After(time.Second):
		t.Fatal("read did not complete after the write released the lock")
	}
}
